package com.example.demo; import com.example.demo.model.User; import com.example.demo.repository.UserRepository; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.data.domain.Sort; @SpringBootTest class UserCustomQueryTest { @Autowired UserRepository r; @Test void testCustomQuerySortingExecution(){r.deleteAll(); for(String[] x:new String[][]{{"Ananya Sen","ananya@aditya.edu.in"},{"Bhavana Reddy","bhavana@aditya.edu.in"},{"Deepak Verma","deepak@aditya.edu.in"},{"Rahul Kumar","rahul@aditya.edu.in"},{"Vijay Sharma","vijay@aditya.edu.in"}})r.save(new User(x[0],x[1])); System.out.println("[@QUERY SORT] Fetching raw output mapping results directly down below:"); r.findAllUsersCustomSorted(Sort.by(Sort.Direction.DESC,"name")).forEach(u->System.out.println(" -> Name: "+u.getName()+" | Email: "+u.getEmail()));} }